function phaserProcess(samples, sr, opts){
  opts = opts || {};
  var rate = opts.rate || 0.5;        // LFO 频率 Hz
  var depth = opts.depth != null ? opts.depth : 0.9;  // 调制深度 0..1
  var stages = opts.stages || 6;      // 全通级数（偶数）
  var mix = opts.mix != null ? opts.mix : 0.5;        // 干湿混合 0..1
  var fb = opts.feedback != null ? opts.feedback : 0.3; // 反馈 0..0.95
  var n = samples.length;
  var out = new Array(n);
  // 全通系数缓存（按各级中心频率）
  if(stages % 2 !== 0) stages += 1;
  var center = [];
  for(var s=0;s<stages;s++){ center.push(200 * Math.pow(15, s/(stages-1||1))); }
  var state = new Array(stages).fill(0);
  var w = 2 * Math.PI * rate / sr;
  var ph = 0;
  for(var i=0;i<n;i++){
    ph += w; if(ph > 2*Math.PI) ph -= 2*Math.PI;
    var lfo = (Math.sin(ph) * 0.5 + 0.5); // 0..1
    var x = samples[i];
    var wet = x;
    var fbSig = 0;
    for(var s=0;s<stages;s++){
      // 调制后的全通中心频率
      var f = center[s] * (1 + depth * (lfo*2-1) * 2);
      if(f < 20) f = 20; if(f > sr*0.45) f = sr*0.45;
      var a = (Math.tan(Math.PI * f / sr) - 1) / (Math.tan(Math.PI * f / sr) + 1);
      var y = a*(x - state[s]) + fbSig - a*(fbSig - state[s]);
      state[s] = y;
      fbSig = y;
      x = y;
    }
    wet = fbSig;
    out[i] = x*(1-mix) + wet*mix;
  }
  return out;
}
function phaserAnalyze(samples, sr, opts){
  var out = phaserProcess(samples, sr, opts);
  var peak=0, sum=0;
  for(var i=0;i<out.length;i++){ var a=Math.abs(out[i]); if(a>peak)peak=a; sum+=out[i]*out[i]; }
  return { length: out.length, peak: peak, rms: Math.sqrt(sum/out.length) };
}

var EXPORTS={phaserProcess:phaserProcess,phaserAnalyze:phaserAnalyze};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PhaserForgePure = EXPORTS; }
